public int findByte(byte value, int pos) {
    // Check if the position is valid
    if (pos < 0 || pos > buffer.length) {
        // If the position is not valid, return -1
        return -1;
    }

    // Loop through the buffer, starting from the specified position
    for (int i = pos; i < buffer.length; i++) {
        // If the byte at the current position is the one we are looking for, return the position
        if (buffer[i] == value) {
            return i;
        }
    }

    // If we reach the end of the buffer without finding the byte, return -1
    return -1;
}

