/**
* Unescapes any Java literals found in the specified string. For example, it will turn a sequence of '\' and 'n' into a newline character, unless the '\' is preceded by another '\'.
* @param str the string to unescape, may be null
* @return a new unescaped string, null if null string input
*/
public static String unescapeJava(String str) throws Exception {
  if (str == null) {
    return null;
  }

  // first pass to replace escaped single quote \' with single quote '
  str = StringUtils.replace(str, "\\'", "'");

  // second pass to replace escaped backslash \\ with backslash \
  str = StringUtils.replace(str, "\\\\", "\\");

  // third pass to replace \n with newline character
  str = StringUtils.replace(str, "\\n", "\n");

  // fourth pass to replace \t with tab character
  str = StringUtils.replace(str, "\\t", "\t");

  return str;
}

